  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% if request.design_mode %}
  8→  {% comment %}
  9→    Theme Editor preview — render a static placeholder so no live API calls
 10→    are made during theme customization. The real widget loads on the storefront.
 11→  {% endcomment %}
 12→  <div style="
 13→    background:#ffffff;
 14→    border:1px solid #e1e3e5;
 15→    border-radius:8px;
 16→    padding:24px;
 17→    max-width:480px;
 18→    font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
 19→    box-sizing:border-box;
 20→    color:#202223;
 21→  ">
 22→    <p style="font-size:16px;font-weight:600;margin:0 0 16px;">Check Delivery Availability</p>
 23→    <div style="display:flex;gap:8px;margin-bottom:12px;">
 24→      <input
 25→        type="text"
 26→        placeholder="Enter your zip code"
 27→        disabled
 28→        style="
 29→          flex:1;padding:10px 12px;border:1px solid #c9cccf;border-radius:8px;
 30→          font-size:14px;background:#fafbfb;color:#202223;min-width:0;
 31→        "
 32→      >
 33→      <button
 34→        type="button"
 35→        disabled
 36→        style="
 37→          background:#008060;color:#fff;border:none;border-radius:8px;
 38→          padding:10px 20px;font-size:14px;font-weight:600;white-space:nowrap;
 39→          opacity:0.7;cursor:default;
 40→        "
 41→      >Check</button>
 42→    </div>
 43→    <div style="
 44→      background:#00806015;border-left:3px solid #008060;border-radius:8px;
 45→      padding:12px;font-size:14px;color:#008060;line-height:1.4;
 46→    ">
 47→      Great news! We deliver to your area.
 48→      <div style="margin-top:4px;font-size:13px;opacity:0.8;">Estimated delivery: 2-3 business days</div>
 49→    </div>
 50→    <p style="margin:12px 0 0;font-size:11px;color:#8c9196;text-align:center;">
 51→      Zip Code Checker — live widget loads on your storefront
 52→    </p>
 53→  </div>
 54→{% else %}
 55→
 56→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
 57→
 58→<div
 59→  id="zcc-widget-{{ block.id }}"
 60→  data-zcc-widget="true"
 61→  data-shop="{{ shop.permanent_domain }}"
 62→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 63→  data-block="{{ block.id }}"
 64→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 65→  {{ block.shopify_attributes }}
 66→></div>
 67→
 68→<script>
 69→(function () {
 70→  // Wait for app embed to set window.__zccAppEnabled.
 71→  // App embed (target: body) may load after this section block, so we poll briefly.
 72→  var maxWait = 3000; // ms
 73→  var interval = 50;  // ms
 74→  var elapsed = 0;
 75→
 76→  function tryInit() {
 77→    if (window.__zccAppEnabled) {
 78→      init();
 79→    } else if (elapsed < maxWait) {
 80→      elapsed += interval;
 81→      setTimeout(tryInit, interval);
 82→    }
 83→    // If app embed is not enabled after 3s, do nothing (merchant hasn't enabled it)
 84→  }
 85→
 86→  // Start checking — if already set, runs immediately
 87→  if (document.readyState === 'loading') {
 88→    document.addEventListener('DOMContentLoaded', tryInit);
 89→  } else {
 90→    tryInit();
 91→  }
 92→
 93→  function init() {
 94→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 95→  var container = document.getElementById(ROOT_ID);
 96→  if (!container) return;
 97→
 98→  var SHOP = container.dataset.shop;
 99→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
100→
101→  // Try embedded config from metafield first (instant, no network needed)
102→  var configStr = container.getAttribute("data-config");
103→  if (configStr) {
104→    try {
105→      renderWidget(JSON.parse(configStr));
106→      return;
107→    } catch (e) {
108→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
109→    }
110→  }
111→
112→  // Fallback: fetch config from API
113→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
114→    .then(function (r) {
115→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
116→      return r.json();
117→    })
118→    .then(function (cfg) { renderWidget(cfg); })
119→    .catch(function (err) {
120→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
121→      renderWidget({});
122→    });
123→
124→  function renderWidget(cfg) {
125→    // Merge with defaults
126→    var D = {
127→      position: "inline",
128→      heading: "Check Delivery Availability",
129→      placeholder: "Enter your zip code",
130→      buttonText: "Check",
131→      successMessage: "Great news! We deliver to your area.",
132→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
133→      notFoundMessage: "This zip code was not found in our system.",
134→      primaryColor: "#008060",
135→      successColor: "#008060",
136→      errorColor: "#D72C0D",
137→      backgroundColor: "#FFFFFF",
138→      textColor: "#202223",
139→      borderRadius: "8",
140→      showEta: true,
141→      showZone: false,
142→      showWaitlistOnFailure: false,
143→      showCod: true,
144→      showReturnPolicy: true,
145→      showCutoffTime: true,
146→      showDeliveryDays: true,
147→      customCss: "",
148→      blockCartOnInvalid: false,
149→      showSocialProof: true,
150→    };
151→    Object.keys(D).forEach(function (k) {
152→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
153→    });
154→
155→    var rad = cfg.borderRadius + "px";
156→    var WID = "zcc-" + ROOT_ID;
157→
158→    if (cfg.position === "floating") {
159→      renderFloating(cfg, WID, rad);
160→    } else if (cfg.position === "popup") {
161→      renderPopup(cfg, WID, rad);
162→    } else {
163→      renderInline(cfg, WID, rad);
164→    }
165→  }
166→
167→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
168→  function injectCss(wid, cfg, rad) {
169→    var css =
170→      "#" + wid + "{" +
171→        "background:" + cfg.backgroundColor + " !important;" +
172→        "color:" + cfg.textColor + " !important;" +
173→        "border-radius:" + rad + " !important;" +
174→        "padding:24px !important;" +
175→        "border:1px solid #e1e3e5 !important;" +
176→        "max-width:480px;" +
177→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
178→        "box-sizing:border-box !important;" +
179→      "}" +
180→      "#" + wid + " *{box-sizing:border-box !important}" +
181→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
182→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
183→      "#" + wid + " .zcc-input{" +
184→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
185→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
186→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
187→      "}" +
188→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
189→      "#" + wid + " .zcc-btn{" +
190→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
191→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
192→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
193→      "}" +
194→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
195→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
196→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
197→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
198→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
199→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
200→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
201→      "#" + wid + " .zcc-wl-input{" +
202→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
203→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
204→      "}" +
205→      "#" + wid + " .zcc-wl-btn{" +
206→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
207→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
208→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
209→      "}" +
210→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
211→      "#" + wid + " .zcc-cutoff{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
212→      "#" + wid + " .zcc-days{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
213→      "#" + wid + " .zcc-cod{margin-top:4px !important;font-size:0.85em !important;font-weight:500 !important}" +
214→      "#" + wid + " .zcc-cod--available{color:#008060 !important}" +
215→      "#" + wid + " .zcc-cod--unavailable{color:#d72c0d !important}" +
216→      "#" + wid + " .zcc-return-policy{margin-top:4px !important;font-size:0.85em !important;color:#6d7175 !important}" +
217→      "#" + wid + " .zcc-social-proof{display:block !important;font-size:0.82em !important;color:#6d7175 !important;margin-bottom:8px !important;font-style:italic !important}" +
218→      (cfg.customCss || "");
219→
220→    var styleEl = document.createElement("style");
221→    styleEl.textContent = css;
222→    document.head.appendChild(styleEl);
223→  }
224→
225→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
226→  function buildWidgetInner(wid, cfg, btnLabel) {
227→    return (
228→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
229→      '<div class="zcc-row">' +
230→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
231→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
232→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
233→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
234→      "</div>" +
235→      '<div id="' + wid + '-res"></div>'
236→    );
237→  }
238→
239→  function wireWidget(wid, cfg, API_BASE, SHOP) {
240→    var inp = document.getElementById(wid + "-inp");
241→    var btn = document.getElementById(wid + "-btn");
242→    var res = document.getElementById(wid + "-res");
243→    var btnLabel = cfg.buttonText;
244→    if (!inp || !btn || !res) return;
245→
246→    function normalizeZip(raw) {
247→      var z = raw.trim().toUpperCase();
248→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
249→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
250→      return z;
251→    }
252→
253→    function checkZip() {
254→      var zip = normalizeZip(inp.value);
255→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
256→      if (!zip) { inp.focus(); return; }
257→
258→      btn.disabled = true;
259→      btn.textContent = "\u2026";
260→      res.innerHTML = "";
261→
262→      fetch(
263→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
264→          "&zip=" + encodeURIComponent(zip)
265→      )
266→        .then(function (r) { return r.json(); })
267→        .then(function (data) {
268→          btn.disabled = false;
269→          btn.textContent = btnLabel;
270→
271→          // Store validation result for cart page
272→          try {
273→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
274→            sessionStorage.setItem('zcc:zip', zip);
275→            sessionStorage.setItem('zcc:shop', SHOP);
276→            // Fire custom event for other scripts to listen to
277→            window.dispatchEvent(new CustomEvent('zcc:validated', {
278→              detail: { valid: data.allowed, zip: zip }
279→            }));
280→          } catch(e) { /* sessionStorage may be unavailable */ }
281→
282→          if (data.allowed) {
283→            var html = '<div class="zcc-result ok">' + esc(data.message);
284→            if (cfg.showEta && data.eta) {
